CREATE OR REPLACE FUNCTION public.product_capacity_for_tenant(request_tenant UUID)
RETURNS TABLE(current_usage BIGINT, limit_value INTEGER, is_unlimited BOOLEAN, included BOOLEAN)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  saved_tenant TEXT := current_setting('app.current_tenant_id', true);
  saved_user TEXT := current_setting('app.current_user_id', true);
  caller TEXT := COALESCE(NULLIF(current_setting('role', true), 'none'), session_user::TEXT);
  plan UUID; used BIGINT; cap INTEGER; enabled BOOLEAN := FALSE;
BEGIN
  -- The owner already has administrative access. Other application callers
  -- must supply the same tenant context as the request. The dedicated worker
  -- may inspect only a tenant with a queued/processing ingestion job.
  IF caller <> current_user::TEXT AND caller <> 'ceopro_ingestion_worker'
     AND public.get_current_tenant() IS DISTINCT FROM request_tenant THEN
    RAISE EXCEPTION 'PRODUCT_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  IF public.get_current_tenant() IS NOT NULL AND public.get_current_tenant() <> request_tenant THEN
    RAISE EXCEPTION 'PRODUCT_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  -- Temporary context is limited to this tenant inside the definer function.
  -- It is restored before returning; caller table privileges/RLS are unchanged.
  PERFORM set_config('app.current_tenant_id', request_tenant::TEXT, true);
  PERFORM set_config('app.current_user_id', COALESCE(NULLIF(saved_user, ''), 'product-capacity-guard'), true);
  IF caller = 'ceopro_ingestion_worker' AND NOT EXISTS (
    SELECT 1 FROM public.ingestion_jobs WHERE tenant_id = request_tenant AND job_status IN ('QUEUED', 'PROCESSING')
  ) THEN RAISE EXCEPTION 'PRODUCT_WORKER_JOB_REQUIRED' USING ERRCODE = '23514'; END IF;
  SELECT count(*) INTO used FROM public.products WHERE tenant_id = request_tenant AND deleted_at IS NULL;
  SELECT plan_id INTO plan FROM public.subscriptions
    WHERE tenant_id = request_tenant AND status IN ('active', 'trialing')
    ORDER BY updated_at DESC, created_at DESC LIMIT 1 FOR SHARE;
  IF plan IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.plan_features pf JOIN public.features f ON f.feature_id = pf.feature_id
    WHERE pf.plan_id = plan AND f.feature_code = 'product_management' AND f.feature_type = 'boolean'
  ) THEN
    SELECT pf.limit_value INTO cap FROM public.plan

CREATE OR REPLACE FUNCTION public.competitor_capacity_for_tenant(request_tenant UUID)
RETURNS TABLE(current_usage BIGINT, limit_value INTEGER, is_unlimited BOOLEAN, included BOOLEAN)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  saved_tenant TEXT := current_setting('app.current_tenant_id', true);
  saved_user TEXT := current_setting('app.current_user_id', true);
  caller TEXT := COALESCE(NULLIF(current_setting('role', true), 'none'), session_user::TEXT);
  plan UUID; used BIGINT; cap INTEGER; enabled BOOLEAN := FALSE;
BEGIN
  -- Application calls require matching tenant context; trigger calls preserve table RLS.
  IF caller <> current_user::TEXT
     AND public.get_current_tenant() IS DISTINCT FROM request_tenant THEN
    RAISE EXCEPTION 'COMPETITOR_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  IF public.get_current_tenant() IS NOT NULL AND public.get_current_tenant() <> request_tenant THEN
    RAISE EXCEPTION 'COMPETITOR_TENANT_REQUIRED' USING ERRCODE = '23514';
  END IF;
  -- Temporary context is limited to this tenant inside the definer function.
  -- It is restored before returning; caller table privileges/RLS are unchanged.
  PERFORM set_config('app.current_tenant_id', request_tenant::TEXT, true);
  PERFORM set_config('app.current_user_id', COALESCE(NULLIF(saved_user, ''), 'competitor-capacity-guard'), true);
  SELECT count(*) INTO used FROM public.tenant_competitors WHERE tenant_id = request_tenant AND is_tracked = TRUE;
  SELECT plan_id INTO plan FROM public.subscriptions
    WHERE tenant_id = request_tenant AND status IN ('active', 'trialing')
    ORDER BY updated_at DESC, created_at DESC LIMIT 1 FOR SHARE;
  IF plan IS NOT NULL AND EXISTS (
    SELECT 1 FROM public.plan_features pf JOIN public.features f ON f.feature_id = pf.feature_id
    WHERE pf.plan_id = plan AND f.feature_code = 'competitor_management' AND f.feature_type = 'boolean'
  ) THEN
    SELECT pf.limit_value INTO cap FROM public.plan_features pf JOIN public.features f ON f.feature_id = pf.feature_id
      WHERE pf.plan_id = plan AND f.feature_code = 'tracked_competitors' AND f.feature_type = 'limit'
        AND f.aggregation_type = 'max' AND f.reset_cycle = 'lifetime';
    enabled := FOUND;
  END IF;
  PERFORM set_config('app.current_tenant_id', COALESCE(saved_tenant, ''), true);
  PERFORM set_config('app.current_user_id', COALESCE(saved

CREATE OR REPLACE FUNCTION public.queue_market_tracking(request_tenant UUID, request_kind TEXT, request_source UUID, request_key TEXT)
RETURNS TABLE(event_id UUID,status TEXT) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE saved_tenant TEXT:=current_setting('app.current_tenant_id',true);
 saved_user TEXT:=current_setting('app.current_user_id',true);
 caller TEXT:=COALESCE(NULLIF(current_setting('role',true),'none'),session_user::TEXT);
BEGIN
 IF caller <> current_user::TEXT AND caller <> 'ceopro_market_dispatcher'
   AND public.get_current_tenant() IS DISTINCT FROM request_tenant THEN
  RAISE EXCEPTION 'MARKET_TENANT_REQUIRED' USING ERRCODE='23514';
 END IF;
 IF request_kind NOT IN ('DISCOVERY','COLLECTION') OR request_key IS NULL OR length(request_key)>250 THEN
  RAISE EXCEPTION 'MARKET_INVALID_REQUEST' USING ERRCODE='23514';
 END IF;
 PERFORM set_config('app.current_tenant_id',request_tenant::TEXT,true);
 PERFORM set_config('app.current_user_id',COALESCE(NULLIF(saved_user,''),'market-tracking-trigger'),true);
 IF NOT EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.plan_features pf ON pf.plan_id=s.plan_id
    JOIN public.features f ON f.feature_id=pf.feature_id JOIN public.companies c ON c.tenant_id=s.tenant_id
    WHERE s.tenant_id=request_tenant AND s.status IN ('active','trialing') AND f.feature_code='competitor_management'
      AND s.plan_id=(SELECT plan_id FROM public.subscriptions WHERE tenant_id=request_tenant AND status IN ('active','trialing') ORDER BY updated_at DESC,created_at DESC LIMIT 1)
      AND c.deleted_at IS NULL AND c.platform_status='active') THEN
  PERFORM set_config('app.current_tenant_id',COALESCE(saved_tenant,''),true);
  PERFORM set_config('app.current_user_id',COALESCE(saved_user,''),true);RETURN;
 END IF;
 IF request_kind='DISCOVERY' AND NOT EXISTS(SELECT 1 FROM public.products WHERE tenant_id=request_tenant AND deleted_at IS NULL) THEN
  PERFORM set_config('app.current_tenant_id',COALESCE(saved_tenant,''),true);
  PERFORM set_config('app.current_user_id',COALESCE(saved_user,''),true);RETURN;
 END IF;
 IF request_kind='COLLECTION' AND NOT EXISTS(
  SELECT 1 FROM public.data_sources ds JOIN public.competitor_product_mappings m ON m.tenant_id=ds.tenant_id AND m.source_id=ds.source_id
   JOIN public.tenant_competitors tc ON tc.tenant_id=m.tenant_id AND tc.global_competitor_id=m.global_comp

